// color_wipe() FX.cpp:262: LEDs turn on in sequence, then off (rev: off in reverse order)
function color_wipe(S, E, rev, useRandomColors) {
	const len = S.len;
	if (len <= 1) return mode_static(S);
	const cycleTime = 750 + (255 - S.speed) * 150;
	const perc = S.now % cycleTime;
	let prog = Math.floor(perc * 65535 / cycleTime);
	const back = prog > 32767;
	if (back) {
		prog -= 32767;
		if (E.step == 0) E.step = 1;
	} else if (E.step == 2) E.step = 3; // trigger color change
	if (useRandomColors) {
		if (E.call == 0) { E.aux0 = hw_random8(); E.step = 3; }
		if (E.step == 1) { E.aux1 = get_random_wheel_index(E.aux0); E.step = 2; } // change to new random color
		if (E.step == 3) { E.aux0 = get_random_wheel_index(E.aux1); E.step = 0; }
	}
	const ledIndex = (prog * len) >>> 15;
	let rem = (prog * len * 2) & 0xFFFF; // uint16: mod 0xFFFF by truncating
	rem = Math.floor(rem / (S.intensity + 1));
	if (rem > 255) rem = 255;
	const col1 = useRandomColors ? S.color_wheel(E.aux1) : S.col[1];
	for (let i = 0; i < len; i++) {
		const index = (rev && back) ? len - 1 - i : i;
		const col0 = useRandomColors ? S.color_wheel(E.aux0) : S.color_from_palette(index, true, S.PALETTE_SOLID_WRAP, 0);
		if (i < ledIndex) S.setPixelColor(index, back ? col1 : col0);
		else {
			S.setPixelColor(index, back ? col0 : col1);
			if (i == ledIndex) S.setPixelColor(index, color_blend(back ? col0 : col1, back ? col1 : col0, rem));
		}
	}
}
