// scan() FX.cpp:467
function scan(S, dual) {
	const len = S.len;
	if (len <= 1) return mode_static(S);
	const cycleTime = 750 + (255 - S.speed) * 150;
	const perc = S.now % cycleTime;
	const prog = Math.floor(perc * 65535 / cycleTime);
	const size = 1 + ((S.intensity * len) >> 9);
	const ledIndex = (prog * (len * 2 - size * 2)) >>> 16;
	if (!S.check2) S.fill(S.col[1]);
	const led_offset = Math.abs(ledIndex - (len - size));
	if (dual) {
		for (let j = led_offset; j < led_offset + size; j++) {
			const i2 = len - 1 - j;
			S.setPixelColor(i2, S.color_from_palette(i2, true, S.PALETTE_SOLID_WRAP, S.col[2] ? 2 : 0));
		}
	}
	for (let j = led_offset; j < led_offset + size; j++) S.setPixelColor(j, S.color_from_palette(j, true, S.PALETTE_SOLID_WRAP, 0));
}
FXS.add("Scan", S => scan(S, false)); // mode_scan() FX.cpp:496
