// running_base() FX.cpp:594: running lights with smooth sine or sawtooth transition
function running_base(S, saw, dual) {
	const len = S.len;
	const x_scale = S.intensity >> 2;
	const counter = Math.imul(S.now, S.speed) >>> 9;
	for (let i = 0; i < len; i++) {
		let a = (i * x_scale - counter) >>> 0;
		if (saw) {
			a &= 0xFF;
			if (a < 16) a = 192 + a * 8;
			else a = map(a, 16, 255, 64, 192);
			a = 255 - a; // may go negative: sin8_t below takes it as uint8
		}
		const s = dual ? sin_gap(a) : sin8_t(a & 0xFF);
		let ca = color_blend(S.col[1], S.color_from_palette(i, true, S.PALETTE_SOLID_WRAP, 0), s);
		if (dual) {
			const b = ((len - 1 - i) * x_scale - counter) >>> 0;
			const t = sin_gap(b);
			const cb = color_blend(S.col[1], S.color_from_palette(i, true, S.PALETTE_SOLID_WRAP, 2), t);
			ca = color_blend(ca, cb, 127);
		}
		S.setPixelColor(i, ca);
	}
}
FXS.add("Running Dual", S => running_base(S, false, true)); // mode_running_dual() FX.cpp:627
FXS.add("Running", S => running_base(S, false, false)); // mode_running_lights() FX.cpp:636
