// mode_flash_sparkle() FX.cpp:784 (flashes = 1 pixel) and mode_hyper_sparkle() FX.cpp:804 (flashes = SEGLEN/3 pixels)
function flash_sparkle(S, E, hyper) {
	if (!S.check2) palFill(S, 0);
	if (((S.now - E.aux0) >>> 0) > E.step) {
		if (hw_random8((255 - S.intensity) >> 4) == 0) {
			const len = hyper ? Math.max(1, Math.trunc(S.len / 3)) : 1;
			for (let i = 0; i < len; i++) S.setPixelColor(hw_random16(S.len), S.col[1]); // flash
		}
		E.step = S.now;
		E.aux0 = 255 - S.speed;
	}
}
