// mode_multi_strobe() FX.cpp:826
FXS.add("Strobe Mega", function(S, E) {
	palFill(S, 1);
	E.aux0 = 50 + 20 * (255 - S.speed);
	const count = 2 * (Math.floor(S.intensity / 10) + 1);
	if (E.aux1 < count) {
		if ((E.aux1 & 1) == 0) {
			S.fill(S.col[0]);
			E.aux0 = 15;
		} else E.aux0 = 50;
	}
	if (((S.now - E.aux0) >>> 0) > E.step) {
		E.aux1 = (E.aux1 + 1) & 0xFFFF;
		if (E.aux1 > count) E.aux1 = 0;
		E.step = S.now;
	}
});

// mode_android() FX.cpp:854; the uint32 counter in SEGENV.data lives in E.s.counter
FXS.add("Android", function(S, E) {
	const len = S.len;
	const counter = E.s.counter || 0;
	let size = E.aux1 >> 1; // upper 15 bit
	let shrinking = E.aux1 & 0x01; // lowest bit
	if (S.now >= E.step) {
		E.step = (S.now + 3 + Math.floor(8 * (255 - S.speed) / len)) >>> 0;
		if (size > Math.floor(S.intensity * len / 255)) shrinking = 1;
		else if (size < 2) shrinking = 0;
		if (!shrinking) { // growing
			if ((counter % 3) == 1) E.aux0 = (E.aux0 + 1) & 0xFFFF; // advance start position
			else size++;
		} else { // shrinking
			E.aux0 = (E.aux0 + 1) & 0xFFFF;
			if ((counter % 3) != 1) size--;
		}
		E.aux1 = (size << 1 | shrinking) & 0xFFFF; // save back
		E.s.counter = (counter + 1) >>> 0;
		if (E.aux0 >= len) E.aux0 = 0;
	}
	const start = E.aux0;
	const end = (E.aux0 + size) % len;
	for (let i = 0; i < len; i++) {
		if ((start < end && i >= start && i < end) || (start >= end && (i >= start || i < end))) S.setPixelColor(i, S.col[0]);
		else S.setPixelColor(i, S.color_from_palette(i, true, S.PALETTE_SOLID_WRAP, 1));
	}
});

// chase() FX.cpp:895: color1 = background, color2/color3 = two adjacent bands
// chase_random replaces the test SEGMENT.mode == FX_MODE_CHASE_RANDOM
function chase(S, E, color1, color2, color3, do_palette, chase_random) {
	const len = S.len;
	const counter = Math.imul(S.now, (S.speed >> 2) + 1) & 0xFFFF;
	const a = ((counter * len) >>> 16) & 0xFFFF;
	if (chase_random) {
		if (a < E.step) { // we hit the start again, choose new color for Chase random
			E.aux1 = E.aux0; // store previous random color
			E.aux0 = get_random_wheel_index(E.aux0);
		}
		color1 = S.color_wheel(E.aux0);
	}
	E.step = a;
	const size = 1 + ((S.intensity * len) >> 10); // intensity varies the chase up to 1/2 string length
	let b = (a + size) & 0xFFFF; // "trail" of chase, filled with color1
	if (b > len) b -= len;
	let c = (b + size) & 0xFFFF;
	if (c > len) c -= len;
	if (do_palette) palFill(S, 1); // background
	else S.fill(color1);
	if (chase_random) { // fill old background between a and end
		color1 = S.color_wheel(E.aux1);
		for (let i = a; i < len; i++) S.setPixelColor(i, color1);
	}
	if (a < b) for (let i = a; i < b; i++) S.setPixelColor(i, color2); // fill between a and b with color2
	else {
		for (let i = a; i < len; i++) S.setPixelColor(i, color2);
		for (let i = 0; i < b; i++) S.setPixelColor(i, color2);
	}
	if (b < c) for (let i = b; i < c; i++) S.setPixelColor(i, color3); // fill between b and c with color3
	else {
		for (let i = b; i < len; i++) S.setPixelColor(i, color3);
		for (let i = 0; i < c; i++) S.setPixelColor(i, color3);
	}
}
FXS.add("Chase", (S, E) => chase(S, E, S.col[1], S.col[2] ? S.col[2] : S.col[0], S.col[0], true, false)); // mode_chase_color() FX.cpp:963
FXS.add("Chase Random", (S, E) => chase(S, E, S.col[1], S.col[2] ? S.col[2] : S.col[0], S.col[0], false, true)); // mode_chase_random() FX.cpp:972

