// mode_colorful() FX.cpp:1009
FXS.add("Colorful", function(S, E) {
	let numColors = 4; // 3, 4, or 5
	const cols = [0x00FF0000, 0x00EEBB00, 0x0000EE00, 0x000077CC, 0, 0, 0, 0, 0];
	if (S.intensity > 160 || S.palette) { // palette or color
		if (!S.palette) {
			numColors = 3;
			for (let i = 0; i < 3; i++) cols[i] = S.col[i];
		} else {
			let fac = 80;
			if (S.palette == 52) { numColors = 5; fac = 61; } // C9 2 has 5 colors
			for (let i = 0; i < numColors; i++) cols[i] = S.color_from_palette(i * fac, false, true, 255);
		}
	} else if (S.intensity < 80) { // pastel (easter) colors
		cols[0] = 0x00FF8040;
		cols[1] = 0x00E5D241;
		cols[2] = 0x0077FF77;
		cols[3] = 0x0077F0F0;
	}
	for (let i = numColors; i < numColors * 2 - 1; i++) cols[i] = cols[i - numColors];
	const cycleTime = 50 + 8 * (255 - S.speed);
	const it = Math.floor(S.now / cycleTime);
	if (it != E.step) {
		if (S.speed > 0) E.aux0 = (E.aux0 + 1) & 0xFFFF;
		if (E.aux0 >= numColors) E.aux0 = 0;
		E.step = it;
	}
	for (let i = 0; i < S.len; i += numColors) {
		for (let j = 0; j < numColors; j++) S.setPixelColor(i + j, cols[E.aux0 + j]);
	}
});

// mode_traffic_light() FX.cpp:1052
FXS.add("Traffic Light", function(S, E) {
	const len = S.len;
	if (len <= 1) return mode_static(S);
	palFill(S, 1);
	let mdelay = 500;
	for (let i = 0; i < len - 2; i += 3) {
		switch (E.aux0) {
			case 0: S.setPixelColor(i, 0x00FF0000); mdelay = 150 + 100 * (255 - S.speed); break;
			case 1: S.setPixelColor(i, 0x00FF0000); mdelay = 150 + 20 * (255 - S.speed); S.setPixelColor(i + 1, 0x00EECC00); break;
			case 2: S.setPixelColor(i + 2, 0x0000FF00); mdelay = 150 + 100 * (255 - S.speed); break;
			case 3: S.setPixelColor(i + 1, gamma32inv(0x00EECC00)); mdelay = 150 + 20 * (255 - S.speed); break; // gamma inversion restores the pre 16.0 look
		}
	}
	if (((S.now - E.step) >>> 0) > mdelay) {
		E.aux0 = (E.aux0 + 1) & 0xFFFF;
		if (E.aux0 == 1 && S.intensity > 140) E.aux0 = 2; // skip Red + Amber, to get US-style sequence
		if (E.aux0 > 3) E.aux0 = 0;
		E.step = S.now;
	}
});

// mode_chase_flash() FX.cpp:1083
FXS.add("Chase Flash", function(S, E) {
	const len = S.len;
	if (len <= 1) return mode_static(S);
	const now = S.now; // save time for delay calculation
	let advance = true;
	const flash_step = E.aux1 % (FLASH_COUNT * 2 + 1);
	if (now < E.step) advance = false; // limit update rate but render every frame for smooth transitions
	else E.aux1 = (E.aux1 + 1) & 0xFFFF;
	palFill(S, 0);
	const n = E.aux0;
	const m = (n + 1) % len;
	let delay = 10 + Math.floor(30 * (255 - S.speed) / len);
	if (flash_step < FLASH_COUNT * 2) {
		if (flash_step % 2 == 0) {
			S.setPixelColor(n, S.col[1]);
			S.setPixelColor(m, S.col[1]);
			delay = 20;
		} else delay = 30;
	} else if (advance) E.aux0 = m; // advance to next position
	if (advance) E.step = (now + delay) >>> 0; // set next update time
});

// mode_chase_flash_random() FX.cpp:1121
FXS.add("Chase Flash Rnd", function(S, E) {
	const len = S.len;
	if (len <= 1) return mode_static(S);
	const now = S.now; // save time for delay calculation
	let advance = true;
	if (now < E.step) {
		E.call = (E.call - 1) >>> 0; // revert increment to skip moving the animation forward and just render the same frame again
		advance = false;
	}
	const flash_step = E.call % (FLASH_COUNT * 2 + 1);
	for (let i = 0; i < E.aux1; i++) S.setPixelColor(i, S.color_wheel(E.aux0));
	let delay = 1 + Math.floor(10 * (255 - S.speed) / len);
	if (flash_step < FLASH_COUNT * 2) {
		const n = E.aux1;
		const m = (E.aux1 + 1) % len;
		if (flash_step % 2 == 0) {
			S.setPixelColor(n, S.col[0]);
			S.setPixelColor(m, S.col[0]);
			delay = 20;
		} else {
			S.setPixelColor(n, S.color_wheel(E.aux0));
			S.setPixelColor(m, S.col[1]);
			delay = 30;
		}
	} else if (advance) {
		E.aux1 = (E.aux1 + 1) % len;
		if (E.aux1 == 0) E.aux0 = get_random_wheel_index(E.aux0);
	}
	if (advance) E.step = (now + delay) >>> 0; // set next update time
});

